// chromeCapturedKeyShares returns the key_share entries for a version.
// The leading GREASE share mirrors Chromium; the PQ share appears once
// the version advertises X25519MLKEM768 in supported_groups.
func chromeCapturedKeyShares(major int) []tls.KeyShare {
	curves := chromeCapturedCurves(major)
	shares := make([]tls.KeyShare, 0, len(curves))
	for _, c := range curves {
		switch c {
		case tls.GREASE_PLACEHOLDER:
			shares = append(shares, tls.KeyShare{Group: tls.GREASE_PLACEHOLDER, Data: []byte{0}})
		case tls.X25519, tls.X25519MLKEM768, tls.CurveP256:
			shares = append(shares, tls.KeyShare{Group: c})
		}
	}
	if len(shares) == 0 {
		shares = []tls.KeyShare{{Group: tls.X25519}}
	}
	return shares
}

