// CapturedChromeMajors lists the Chrome major versions with a capture,
// newest first.  Used by the binding to expose the generated profiles.
func CapturedChromeMajors() []int {
	out := make([]int, len(chromeCapturedMajors))
	for i, m := range chromeCapturedMajors {
		out[i] = m
	}
	return out
}
